package com.example.myapplication.coreimport com.google.gson.GsonBuilderimport retrofit2.Retrofitimport retrofit2.converter.gson.GsonConverterFactoryobject Api {    //172.19.80.1    private val URL = "http://172.19.80.1:3000/"    private var gson = GsonBuilder().create()    val retrofit = Retrofit.Builder()        .baseUrl(URL)        .addConverterFactory(GsonConverterFactory.create(gson))        .build()}